// Shim for @rollup/rollup-linux-x64-gnu
// This stub allows rollup to load on linux-x64 environments
// where the native binary may not be installed via npm optional deps

const path = require('path');
const fs = require('fs');

// Try to find the actual binary in common locations
const possiblePaths = [
  path.join(__dirname, 'rollup.linux-x64-gnu.node'),
  path.join(__dirname, '..', '..', 'rollup', 'dist', 'rollup.linux-x64-gnu.node'),
];

let nativeBinding = null;

for (const p of possiblePaths) {
  if (fs.existsSync(p)) {
    try {
      nativeBinding = require(p);
      break;
    } catch (e) {
      // continue
    }
  }
}

if (!nativeBinding) {
  // Provide empty stubs so rollup can fall back to WASM or JS implementation
  module.exports = {};
}  else {
  module.exports = nativeBinding;
}
